from html import escape

BASE='/assets/un-day-2026/'
PHOTOS=[('chairs.jpg','The committee chairs open the UN Day simulation.'),('chair-speaking.jpg','Guiding delegates through the emergency session.'),('dais.jpg','The Model UN dais in Akron Law’s courtroom.'),('preparation.jpg','Coordinating the next stage of debate.'),('caucus-1.jpg','Delegates exchange perspectives during caucus.'),('caucus-2.jpg','Working together on a diplomatic response.'),('caucus-3.jpg','Coalition building on the committee floor.'),('group.jpg','UN Day participants at The University of Akron.'),('diplomacy.jpg','Outstanding Diplomacy — China delegation.'),('speaker.jpg','Best Speaker — Jesse, Russian Federation.'),('honorable.jpg','Honorable Mention — Sabina, United States.'),('delegate.jpg','Best Delegate — Isabelle, United Kingdom.')]
def image(name,alt,cls='',eager=False):
    return f'<img class="{cls}" src="{BASE}{name}" alt="{escape(alt,quote=True)}" loading="{"eager" if eager else "lazy"}" decoding="async">'
def stats(items):
    return '<div class="impact-strip">'+''.join(f'<div><strong>{n}</strong><span>{s}</span></div>' for n,s in items)+'</div>'
def cards(items):
    return '<div class="new-cards">'+''.join(f'<article><span class="eyebrow">{tag}</span><h3>{title}</h3><p>{body}</p></article>' for tag,title,body in items)+'</div>'
def heading(tag,title,desc):
    return f'<header class="editorial-hero"><div class="wrap"><span class="eyebrow">{tag}</span><h1>{title}</h1><p>{desc}</p></div></header>'
def page(title,desc,body): return dict(title=title+' | UNA-USA Akron',description=desc,body=body)
