CSS=r'''
:root{--navy:#091e30;--gold:#e4ba70;--blue:#245f89;--line:#d7dfe3}body{background:#f5f5f0}h1,h2,h3{letter-spacing:-.035em}h1{line-height:1.02}.site-header{position:sticky;top:0;z-index:50;background:#091e30f5;backdrop-filter:blur(14px);color:#fff;border-bottom:1px solid #ffffff20}.site-header .brand,.site-header .nav a{color:#fff}.site-header .brand small{color:#bbccd7}.nav a{font-size:.85rem}.nav a[aria-current=page]{color:var(--gold);border-color:var(--gold)}.site-header .menu-toggle{color:#fff;border:1px solid #6c7d89;background:transparent}.button{transition:transform .2s,box-shadow .2s}.button:hover{transform:translateY(-3px);box-shadow:0 7px 20px #0002}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #e4ba70;outline-offset:5px}button,summary{cursor:pointer}html{scroll-behavior:smooth;scroll-padding-top:110px}.modern-main{padding-bottom:5rem}.editorial-hero{padding:6rem 0 4.5rem;background:#091e30;color:#fff}.editorial-hero h1{font-size:clamp(3.2rem,7vw,6.6rem);max-width:1000px;margin:1.1rem 0 1.6rem}.editorial-hero p{max-width:660px;font-size:1.2rem;color:#c5d4dd}.editorial-hero .eyebrow{color:#e4ba70}.new-home{position:relative;isolation:isolate;background:#071a2a;color:#fff;min-height:740px;display:flex;align-items:center}.home-photo{position:absolute;inset:0;z-index:-2}.home-photo img{width:100%;height:100%;object-fit:cover;object-position:center 45%}.new-home:after{content:'';position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,#061522ee 0%,#061522ba 42%,#06152215 100%),linear-gradient(0deg,#061522ab,transparent 60%)}.home-copy{padding-top:6rem;padding-bottom:4rem}.home-copy h1{font-size:clamp(3.4rem,7.8vw,7.5rem);margin:1.4rem 0;max-width:800px;color:#fff}.home-copy p{font-size:1.2rem;line-height:1.65;color:#e3eaf0;max-width:600px}.home-copy .eyebrow{color:#e4ba70}.hero-foot{display:block;font-size:.8rem;letter-spacing:.14em;text-transform:uppercase;margin-top:4rem;color:#d1dce4}.impact-strip{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--line);padding:2.6rem 0;gap:1.5rem}.impact-strip strong{display:block;font-size:clamp(2.3rem,4.5vw,4rem);font-weight:500;letter-spacing:-.05em;color:#133a55}.impact-strip span{display:block;font-size:.85rem;color:#4c606d}.pathways{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#cbd6db;border:1px solid #cbd6db}.pathways a{background:#fff;padding:2.4rem;text-decoration:none;transition:background .25s,transform .25s}.pathways a:hover{background:#e6eef3;transform:translateY(-5px)}.pathways span{font-size:.75rem;text-transform:uppercase;letter-spacing:.1em;color:#52748c}.pathways h3{font-size:2.4rem;font-family:Georgia,serif;margin:2rem 0 1rem}.pathways p{color:#4c606d;min-height:80px}.pathways b{font-size:.9rem;color:#245f89}.recap-card{display:grid;grid-template-columns:1.1fr 1fr;background:#091e30;color:#fff;text-decoration:none;margin:3rem 0;overflow:hidden}.recap-card>img{width:100%;height:100%;min-height:380px;object-fit:cover;transition:transform .6s}.recap-card:hover>img{transform:scale(1.025)}.recap-card>div{padding:3rem;align-self:center}.recap-card h2{color:#fff;font-size:clamp(2rem,3.3vw,3.5rem);line-height:1.1}.recap-card p{color:#c5d4dd}.recap-card .eyebrow,.text-link{color:#e4ba70}.text-link{display:inline-block;margin-top:1rem;font-weight:700}.research-callout{padding:3.5rem;background:#e6edf0;border-top:4px solid #d3a85e;margin:3rem 0}.research-callout h2{font-size:3.4rem;line-height:1.05;margin:1rem 0}.research-callout p{max-width:780px}.new-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;margin:2.5rem 0}.new-cards article{border:1px solid var(--line);background:#fff;padding:2rem}.new-cards h3{font:2rem Georgia,serif;line-height:1.15;margin:.8rem 0}.new-cards p{color:#526470}.new-cards .eyebrow{color:#526470}.filter-bar{display:flex;gap:.7rem;flex-wrap:wrap;margin:2rem 0}.filter-bar button,.stage-controls button,.spread-timeline button{font:inherit;border:1px solid #b8c7d0;background:transparent;padding:.75rem 1.2rem}.filter-bar button[aria-pressed=true]{background:#091e30;color:#fff}.archive-record{padding:3rem 0;border-top:1px solid var(--line)}.archive-record h2{font-size:2.6rem}.milestone-list{list-style:none;padding:0}.milestone-list li{display:grid;grid-template-columns:220px 1fr;gap:2rem;padding:1.3rem 0;border-top:1px solid var(--line)}.recap-hero{background:#091e30;color:#fff;padding-top:2rem}.recap-hero h1{font-size:clamp(3.3rem,7vw,6.8rem);margin:1.5rem 0}.recap-hero .eyebrow{display:block;color:#e4ba70}.recap-hero p{color:#c5d4dd;padding-bottom:2rem}.back-link{display:block;margin-bottom:2.5rem;font-size:.9rem;color:inherit}.recap-wide{width:100%;max-height:680px;object-fit:cover;object-position:center 42%;display:block}.crisis-teaser{display:grid;grid-template-columns:1fr 260px;gap:2rem;align-items:center;background:#090909;color:#f2f0e9;padding:3.5rem;text-decoration:none;border-top:5px solid #ff4017}.crisis-teaser h2{color:#f2f0e9;font:600 clamp(2.5rem,5vw,4rem)/1.02 Arial,sans-serif}.crisis-teaser img{width:100%}.crisis-teaser .eyebrow,.crisis-teaser .text-link{color:#ff6a42}.photo-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}.photo-grid a,.briefing-gallery a{text-decoration:none;display:block;background:#fff;overflow:hidden}.photo-grid img{width:100%;aspect-ratio:4/3;object-fit:cover;transition:transform .35s}.photo-grid a:nth-child(n+9) img{aspect-ratio:3/4;object-position:center}.photo-grid a:hover img{transform:scale(1.025)}.photo-grid span,.briefing-gallery span{display:block;padding:1rem;font-size:.85rem}.social-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem}.social-grid a{display:flex;flex-direction:column;gap:1rem;text-decoration:none;border:1px solid var(--line);padding:1.5rem}.social-grid span{font-size:.8rem;color:#526470}.program-details{padding:1.5rem;border:1px solid var(--line)}.program-details summary{font-weight:bold}.crisis-page{background:#090909;color:#eae9e4;position:relative;overflow:hidden;padding:2rem 0 4rem;font-family:Arial,sans-serif}.crisis-page>.wrap{position:relative;z-index:1}.crisis-page h1,.crisis-page h2{font-family:Arial,sans-serif;font-weight:800;letter-spacing:-.045em}.crisis-page .eyebrow{color:#ff7048;font-family:monospace;letter-spacing:.13em}.crisis-page p{line-height:1.8;color:#bbbcb8;max-width:950px}.crisis-page a{color:inherit}.crisis-grid{position:absolute;inset:0;background-image:linear-gradient(#ff401708 1px,transparent 1px),linear-gradient(90deg,#ff401708 1px,transparent 1px);background-size:55px 55px;pointer-events:none}.crisis-heading{display:grid;grid-template-columns:1.35fr 1fr;gap:3rem;align-items:center;padding:1rem 0 5rem}.crisis-heading h1{font-size:clamp(3.4rem,7.8vw,7.4rem);line-height:.96;margin:2rem 0}.crisis-heading em{font-style:normal;color:#ff4017}.simulation-label{display:block;color:#ddd;font-size:.8rem;border-left:3px solid #ff4017;padding:.6rem 1rem;margin-bottom:2rem;background:#ffffff08}.vespr-emblem{position:relative;text-align:center}.vespr-emblem:before{content:'';position:absolute;inset:-8%;border:1px solid #ff401744;border-radius:50%;animation:radar 6s ease-in-out infinite;pointer-events:none}.vespr-emblem img{width:100%;max-width:400px}.vespr-emblem span{display:block;font:12px monospace;letter-spacing:.25em;color:#ff7048;margin-top:2rem}.crisis-page .crisis-button{background:#ff4017;color:#0a0a0a;font-weight:bold;border:none}.hazard-band{display:flex;align-items:center;justify-content:space-between;border-block:1px solid #ff401766;padding:.9rem 1rem;color:#ff7048;font:12px monospace;letter-spacing:.15em;background:repeating-linear-gradient(135deg,transparent 0,transparent 16px,#ff401707 16px,#ff401707 32px)}.hazard-band span{font-size:2rem}.crisis-question{padding:5rem 0}.crisis-question h2{font-size:clamp(2rem,3.5vw,3.5rem);line-height:1.15;max-width:1000px}.crisis-page .scenario-note{font-size:.9rem;border-left:2px solid #555;padding-left:1rem}.stage-controls{display:flex;gap:1rem;border-bottom:1px solid #444;padding-bottom:1rem}.stage-controls button{color:#ccc;border-color:#555;flex:1}.stage-controls button[aria-pressed=true]{background:#ff4017;color:#090909;border-color:#ff4017}.stage-panel{padding:3rem 0;min-height:310px}.stage-panel h2{font-size:clamp(2.3rem,4vw,4rem);margin:.8rem 0}.stage-panel p{font-size:1.15rem}.stage-panel[hidden],[data-category][hidden]{display:none}.spread-section{padding:3rem;background:#131313;border:1px solid #383838}.spread-section h2{font-size:2.8rem;line-height:1.1}.spread-timeline{display:flex;gap:.8rem;flex-wrap:wrap}.spread-timeline button{color:#ccc;border-color:#555}.spread-timeline button[aria-pressed=true]{border-color:#ff4017;color:#ff7048}.crisis-page .day-detail{min-height:72px;font-size:1.2rem;color:#eee}.deal-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}.deal-grid details{background:#131313;border-top:3px solid #ff4017;padding:1.5rem}.deal-grid summary{font-size:1.35rem;font-weight:bold}.deal-grid strong{color:#ff7048;font-size:.9rem}.directive{border-block:1px solid #ff401755;padding:3rem 0}.directive h2{font-size:3rem}.briefing-gallery{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem}.briefing-gallery a{background:#151515}.briefing-gallery img{width:100%;display:block}.gallery-dialog{padding:1rem;border:1px solid #555;background:#0b0e12;color:white;max-width:95vw;max-height:95vh;width:1100px}.gallery-dialog::backdrop{background:#000e}.gallery-dialog img{width:100%;height:70vh;object-fit:contain;display:block}.gallery-tools{display:flex;justify-content:space-between;gap:1rem;align-items:center}.gallery-tools button{background:#182e40;color:white;border:1px solid #7a8a96;padding:.6rem 1rem;font:inherit}.gallery-caption{font-size:.9rem}.reveal-in{animation:rise .7s ease both}@keyframes rise{from{opacity:.35;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}@keyframes radar{50%{transform:scale(1.08);opacity:.4}}@media(max-width:1050px){.nav{gap:1rem}.nav a{font-size:.78rem}.crisis-heading{gap:1.5rem}.social-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:800px){.site-header .nav{background:#091e30}.pathways{grid-template-columns:1fr}.pathways p{min-height:0}.pathways h3{margin:1rem 0}.recap-card{grid-template-columns:1fr}.recap-card>img{min-height:0;max-height:400px}.crisis-heading{grid-template-columns:1fr}.vespr-emblem{max-width:220px;margin:1rem auto 0}.crisis-teaser{grid-template-columns:1fr 160px;padding:2rem}.deal-grid{grid-template-columns:1fr}.new-home{min-height:690px}.photo-grid{grid-template-columns:repeat(2,1fr)}.impact-strip{grid-template-columns:repeat(2,1fr)}.new-cards{grid-template-columns:1fr}.home-copy{padding-top:4rem}.home-photo img{object-position:65% center}.new-home:after{background:#061522bb}.stage-controls{flex-direction:column}.milestone-list li{grid-template-columns:1fr;gap:.5rem}}@media(max-width:520px){.crisis-teaser{grid-template-columns:1fr}.crisis-teaser img{max-width:150px}.recap-card>div,.research-callout,.spread-section{padding:1.5rem}.research-callout h2{font-size:2.7rem}.photo-grid,.briefing-gallery,.social-grid{grid-template-columns:1fr}.editorial-hero{padding:4rem 0 3rem}.hazard-band{letter-spacing:0}.gallery-tools{flex-wrap:wrap}.gallery-dialog img{height:60vh}.home-copy .eyebrow{font-size:.65rem}.crisis-heading h1{font-size:3.4rem}.new-cards article{padding:1.5rem}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation:none!important;transition:none!important}}
'''
JS=r'''
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-category]').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.category!==b.dataset.filter)}));
const stageButtons=[...document.querySelectorAll('[data-stage]')];function setStage(n){stageButtons.forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.stage===n)));document.querySelectorAll('.stage-panel').forEach((p,i)=>p.hidden=i!==n)}if(stageButtons.length){setStage(0);stageButtons.forEach(b=>b.addEventListener('click',()=>setStage(+b.dataset.stage)))}
const days=['The fictional outbreak begins at major EU airports; the attackers are apprehended after the disease has spread.','Within four days, the fictional disease has reached every P5 and G4 nation.','On day five, the World Health Organization declares a global pandemic within the simulation.','By day six, every Member State in the scenario reports symptoms in at least 10% of its population.'];document.querySelectorAll('[data-day]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-day]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('day-detail').textContent=days[+b.dataset.day]}));
const photos=[...document.querySelectorAll('[data-gallery]')];if(photos.length){const d=document.createElement('dialog');d.className='gallery-dialog';d.setAttribute('aria-label','Event photo and briefing gallery');d.innerHTML='<div class="gallery-tools"><button type="button" data-prev aria-label="Previous image">← Previous</button><span data-count></span><button type="button" data-next aria-label="Next image">Next →</button><button type="button" data-close>Close ×</button></div><img alt=""><p class="gallery-caption"></p>';document.body.append(d);let current=0;function show(i){current=(i+photos.length)%photos.length;const p=photos[current];d.querySelector('img').src=p.href;d.querySelector('img').alt=p.dataset.caption;d.querySelector('.gallery-caption').textContent=p.dataset.caption;d.querySelector('[data-count]').textContent=(current+1)+' / '+photos.length}photos.forEach((p,i)=>p.addEventListener('click',e=>{e.preventDefault();show(i);d.showModal()}));d.querySelector('[data-close]').onclick=()=>d.close();d.querySelector('[data-prev]').onclick=()=>show(current-1);d.querySelector('[data-next]').onclick=()=>show(current+1);d.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();show(current-1)}if(e.key==='ArrowRight'){e.preventDefault();show(current+1)}});d.addEventListener('click',e=>{if(e.target===d&&e.offsetY<0)d.close()})}
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('reveal-in');o.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.new-cards article,.archive-record,.pathways a,.research-callout').forEach(e=>o.observe(e))}
'''
